import subtopicsByTopic from "@/content/subtopics.json";
import type { Paper, Subtopic, Topic } from "./types";

// Generated by scripts/validate-content.mjs from content/subtopics/<topicId>.json.
const SUBTOPICS = subtopicsByTopic as Record<string, Subtopic[]>;

// MD Pharmacology theory papers exactly as in the NMC "Guidelines for Competency Based Postgraduate
// Training Programme for MD in Pharmacology" (revised, 01-08-2022; text in design/NMC-MD-Pharmacology-2022.txt).
// Each topic lists the NMC syllabus item numbers it covers (point-to-point mapping) and its textbook chapters.
// Topic ids are permanent (card ids depend on them); only their paper placement follows NMC.
type T = [id: string, title: string, nmc: number[], refs: string[]];

const p = (id: string, title: string, topics: T[]): Paper => ({
  id,
  title,
  topics: topics.map(([tid, t, nmc, refs]) => ({ id: tid, paperId: id, title: t, nmc, refs, subtopics: SUBTOPICS[tid] ?? [] })),
});

